messages.content:
Tool response:
Tool: create_ad_hoc_task
Description: Create Ad Hoc Task
Parameters:
    {
      "type": "object",
      "properties": {
        "title": {
          "type": "string",
          "title": "Title"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description"
        },
        "assignee_name": {
          "type": "string",
          "title": "Assignee Name"
        },
        "protocol_name": {
          "type": "string",
          "title": "Protocol Name"
        },
        "protocol_version": {
          "type": "string",
          "title": "Protocol Version"
        },
        "due_date": {
          "type": "string",
          "title": "Due Date"
        },
        "priority": {
          "type": "string",
          "enum": [
            "Low",
            "Medium",
            "High",
            "Critical"
          ],
          "title": "Priority"
        },
        "status": {
          "type": "string",
          "enum": [
            "Not Started",
            "In Progress",
            "Completed",
            "Blocked",
            "Cancelled"
          ],
          "title": "Status"
        }
      },
      "required": [
        "title",
        "assignee_name",
        "protocol_name",
        "protocol_version",
        "due_date",
        "priority",
        "status"
      ]
    }
